@startuml

class Researcher {
  + name : string
  + surname : string
  + researchGroup : ResearchGroup
}

class ResearchGroup {
  + name : string
  + department : Department
  + leader : Researcher
}

class WorkPackage {
  + id : int
  + title : string
  + leader : ResearchGroup
}

class Department {
  + name : string
}

Researcher "1" -- "1" ResearchGroup : belongsTo
Researcher "*" -- "*" WorkPackage : assignedTo
WorkPackage "1" -- "1" ResearchGroup : leads

@enduml

